import "server-only";

import { and, eq, inArray, isNotNull, ne, notExists, sql } from "drizzle-orm";

import {
  addGroupMember,
  createWorkspaceUser,
  type Actor,
  listManageableGroups,
  type ManageableGroup,
} from "@/lib/directory";
import { getDb } from "@/lib/db";
import { captureReviewerMail } from "@/lib/review";
import { signupRequest, signupRequestGroup, signupRequestRevision } from "@/lib/schema";

const provisioningStatuses = [
  "accepted",
  "provisioning",
  "awaiting_handover",
  "handover_confirmed",
];

// The decision is one conditional update, so repeated or concurrent accepts yield one winner.
export async function acceptSignupRequest(id: string, approverDirectoryId: string) {
  const [accepted] = await getDb()
    .update(signupRequest)
    .set({ status: "accepted", acceptedAt: new Date(), approvedByDirectoryId: approverDirectoryId })
    .where(
      and(
        eq(signupRequest.id, id),
        eq(signupRequest.status, "verified"),
        isNotNull(signupRequest.workspaceEmail),
      ),
    )
    .returning({ id: signupRequest.id });
  return Boolean(accepted);
}

// Only the caller that moves accepted -> provisioning creates the account, and `attempting`
// is persisted in that same statement, so an interrupted create is never silently repeated.
// ponytail: runs inline in the accept request; an uncertain create waits for reconciliation (#11).
export async function provisionAcceptedRequest(id: string, actor: Actor) {
  const db = getDb();
  const [claimed] = await db
    .update(signupRequest)
    .set({ status: "provisioning", accountCreateState: "attempting" })
    .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "accepted")))
    .returning({
      workspaceEmail: signupRequest.workspaceEmail,
      givenName: signupRequest.givenName,
      familyName: signupRequest.familyName,
    });
  if (!claimed?.workspaceEmail) return;

  let userId: string;
  try {
    userId = (
      await createWorkspaceUser(actor, {
        email: claimed.workspaceEmail,
        givenName: claimed.givenName,
        familyName: claimed.familyName,
      })
    ).id;
  } catch {
    // Any failure may have reached Google: keep it for reconciliation, do not repeat it.
    await db
      .update(signupRequest)
      .set({ accountCreateState: "uncertain" })
      .where(eq(signupRequest.id, id));
    return;
  }
  await db
    .update(signupRequest)
    .set({ accountCreateState: "created", googleUserId: userId })
    .where(eq(signupRequest.id, id));

  await addUnfinishedMemberships(id, userId);
  await completeIfAllAdded(id);
}

// Touches only `pending` and `failed` groups, so successful memberships are never re-sent.
// ponytail: overlapping retries can both try one unfinished group; the real Directory call (#11)
// must treat "already a member" as success.
async function addUnfinishedMemberships(id: string, userId: string) {
  const db = getDb();
  const groups = await db
    .select()
    .from(signupRequestGroup)
    .where(
      and(
        eq(signupRequestGroup.signupRequestId, id),
        inArray(signupRequestGroup.state, ["pending", "failed"]),
      ),
    );
  for (const group of groups) {
    let state = "added";
    try {
      await addGroupMember(group.groupId, userId, group.role);
    } catch {
      state = "failed";
    }
    await db
      .update(signupRequestGroup)
      .set({ state })
      .where(
        and(
          eq(signupRequestGroup.signupRequestId, id),
          eq(signupRequestGroup.groupId, group.groupId),
        ),
      );
  }
}

// One conditional statement: handover is reached only when no selected membership is unfinished,
// even if a revision or another retry runs at the same time.
async function completeIfAllAdded(id: string) {
  await getDb()
    .update(signupRequest)
    .set({ status: "awaiting_handover" })
    .where(
      and(
        eq(signupRequest.id, id),
        eq(signupRequest.status, "provisioning"),
        eq(signupRequest.accountCreateState, "created"),
        notExists(
          getDb()
            .select({ one: sql`1` })
            .from(signupRequestGroup)
            .where(
              and(
                eq(signupRequestGroup.signupRequestId, id),
                ne(signupRequestGroup.state, "added"),
              ),
            ),
        ),
      ),
    );
}

// Retries only unfinished memberships. An unknown account outcome is never repeated here.
export async function retryProvisioning(
  id: string,
): Promise<"retried" | "uncertain" | "unavailable"> {
  const [request] = await getDb()
    .select({
      status: signupRequest.status,
      state: signupRequest.accountCreateState,
      googleUserId: signupRequest.googleUserId,
    })
    .from(signupRequest)
    .where(eq(signupRequest.id, id));
  if (request?.status !== "provisioning") return "unavailable";
  if (request.state !== "created" || !request.googleUserId) return "uncertain";
  await addUnfinishedMemberships(id, request.googleUserId);
  await completeIfAllAdded(id);
  return "retried";
}

export type AssignmentRevision = {
  groupId: string;
  replacement?: { groupId: string; groupEmail: string; role: "member" | "manager" | "owner" };
};

// Removes or replaces one unfinished assignment and records why. Successful memberships are
// never touched. Returns false when the request or assignment is not revisable.
export async function reviseAssignment(
  id: string,
  revision: AssignmentRevision,
  adminDirectoryId: string,
) {
  return getDb().transaction(async (tx) => {
    const [request] = await tx
      .select({ status: signupRequest.status })
      .from(signupRequest)
      .where(eq(signupRequest.id, id))
      .for("update");
    if (request?.status !== "provisioning") return false;
    const [removed] = await tx
      .delete(signupRequestGroup)
      .where(
        and(
          eq(signupRequestGroup.signupRequestId, id),
          eq(signupRequestGroup.groupId, revision.groupId),
          ne(signupRequestGroup.state, "added"),
        ),
      )
      .returning();
    if (!removed) return false;
    const { replacement } = revision;
    if (replacement)
      await tx.insert(signupRequestGroup).values({ ...replacement, signupRequestId: id });
    await tx.insert(signupRequestRevision).values({
      signupRequestId: id,
      removedGroupId: removed.groupId,
      removedGroupEmail: removed.groupEmail,
      replacementGroupId: replacement?.groupId,
      replacementGroupEmail: replacement?.groupEmail,
      replacementRole: replacement?.role,
      revisedByDirectoryId: adminDirectoryId,
    });
    return true;
  });
}

// Records that first-login instructions were sent (not delivered, not used). One conditional
// statement, so it needs provisioning complete and every selected membership added, and only one
// concurrent confirmation wins.
export async function confirmHandover(
  id: string,
  adminDirectoryId: string,
): Promise<"confirmed" | "already" | "blocked" | "unavailable"> {
  const db = getDb();
  const [confirmed] = await db
    .update(signupRequest)
    .set({
      status: "handover_confirmed",
      handoverConfirmedAt: new Date(),
      handoverConfirmedByDirectoryId: adminDirectoryId,
    })
    .where(
      and(
        eq(signupRequest.id, id),
        eq(signupRequest.status, "awaiting_handover"),
        eq(signupRequest.accountCreateState, "created"),
        notExists(
          db
            .select({ one: sql`1` })
            .from(signupRequestGroup)
            .where(
              and(
                eq(signupRequestGroup.signupRequestId, id),
                ne(signupRequestGroup.state, "added"),
              ),
            ),
        ),
      ),
    )
    .returning({ id: signupRequest.id });
  if (confirmed) {
    try {
      await captureReviewerMail(
        id,
        "Workspace account handover confirmed",
        "An administrator confirmed that first-login instructions were sent.",
      );
    } catch {
      // ponytail: the confirmation stands; this notice is not retried.
    }
    return "confirmed";
  }
  const [request] = await db
    .select({ status: signupRequest.status })
    .from(signupRequest)
    .where(eq(signupRequest.id, id));
  if (request?.status === "handover_confirmed") return "already";
  return request && provisioningStatuses.includes(request.status) ? "blocked" : "unavailable";
}

// Undefined until the request has been accepted.
export async function getProvisioningProgress(id: string, actor: Actor) {
  const db = getDb();
  const [request] = await db
    .select({
      status: signupRequest.status,
      workspaceEmail: signupRequest.workspaceEmail,
      acceptedAt: signupRequest.acceptedAt,
      handoverConfirmedAt: signupRequest.handoverConfirmedAt,
      googleUserId: signupRequest.googleUserId,
      accountCreateState: signupRequest.accountCreateState,
    })
    .from(signupRequest)
    .where(eq(signupRequest.id, id));
  if (!request || !provisioningStatuses.includes(request.status)) return undefined;
  const groups = await db
    .select({
      groupId: signupRequestGroup.groupId,
      groupEmail: signupRequestGroup.groupEmail,
      role: signupRequestGroup.role,
      state: signupRequestGroup.state,
    })
    .from(signupRequestGroup)
    .where(eq(signupRequestGroup.signupRequestId, id));
  // Unfinished groups the acting administrator can no longer manage; null when the Directory is unreachable.
  let choices: ManageableGroup[] | null = null;
  if (groups.some((group) => group.state !== "added")) {
    try {
      choices = await listManageableGroups(actor);
    } catch {
      // Progress stays readable without the Directory.
    }
  }
  const manageable = choices && new Set(choices.map((group) => group.id));
  const selected = new Set(groups.map((group) => group.groupId));
  return {
    ...request,
    // Replacement options for an unfinished assignment: manageable and not already selected.
    choices: choices?.filter((group) => !selected.has(group.id)) ?? [],
    groups: groups.map((group) => ({
      ...group,
      manageable: manageable?.has(group.groupId) ?? null,
    })),
  };
}
import "server-only";

import { randomBytes } from "node:crypto";

import { z } from "zod";

import { googleGet, googleSend, WorkspaceUnavailable } from "@/lib/workspace";

export type ManageableGroup = { id: string; email: string; name: string };

// The acting administrator whose OAuth grant makes every Directory call. There is no fallback
// credential: a denied call is reported, never retried with anything stronger.
export type Actor = { accessToken: string; profile: { id: string } };

const directory = "https://admin.googleapis.com/admin/directory/v1";

const assignmentsSchema = z.object({
  items: z.array(z.object({ roleId: z.string() })).optional(),
  nextPageToken: z.string().optional(),
});
const roleSchema = z.object({
  isSuperAdminRole: z.boolean().optional(),
  rolePrivileges: z.array(z.object({ privilegeName: z.string() })).optional(),
});
const createdUserSchema = z.object({ id: z.string().min(1) });
const groupsSchema = z.object({
  groups: z.array(z.object({ id: z.string(), email: z.string(), name: z.string() })).optional(),
  nextPageToken: z.string().optional(),
});

async function* pages<T extends { nextPageToken?: string }>(
  url: URL,
  accessToken: string,
  schema: z.ZodType<T>,
) {
  let pageToken: string | undefined;
  do {
    if (pageToken) url.searchParams.set("pageToken", pageToken);
    const page = schema.parse(await googleGet(url, accessToken));
    yield page;
    pageToken = page.nextPageToken;
  } while (pageToken);
}

// An address is taken by any user or group (aliases resolve to their owner).
export async function isWorkspaceEmailAvailable(actor: Actor, email: string) {
  const key = encodeURIComponent(email.toLowerCase());
  for (const kind of ["users", "groups"]) {
    if (await googleGet(`${directory}/${kind}/${key}?fields=id`, actor.accessToken, true))
      return false;
  }
  return true;
}

// Google has no "can I write this group" probe, and group writes are gated by admin role
// privileges across the customer, not per group. So the administrator either can write every
// group (super admin, or a held role with GROUPS_ALL) or none.
// ponytail: narrower Groups privileges (e.g. Groups Editor) count as "none"; widen if needed.
async function canWriteGroups({ accessToken, profile }: Actor) {
  const url = new URL(`${directory}/customer/my_customer/roleassignments`);
  url.searchParams.set("userKey", profile.id);
  url.searchParams.set("includeIndirectRoleAssignments", "true");
  const roleIds = new Set<string>();
  for await (const page of pages(url, accessToken, assignmentsSchema))
    for (const item of page.items ?? []) roleIds.add(item.roleId);
  for (const roleId of roleIds) {
    const role = roleSchema.parse(
      await googleGet(
        `${directory}/customer/my_customer/roles/${encodeURIComponent(roleId)}`,
        accessToken,
      ),
    );
    if (role.isSuperAdminRole || role.rolePrivileges?.some((p) => p.privilegeName === "GROUPS_ALL"))
      return true;
  }
  return false;
}

export async function listManageableGroups(actor: Actor): Promise<ManageableGroup[]> {
  if (!(await canWriteGroups(actor))) return [];
  const url = new URL(`${directory}/groups`);
  url.searchParams.set("customer", "my_customer");
  url.searchParams.set("maxResults", "200");
  url.searchParams.set("fields", "nextPageToken,groups(id,email,name)");
  const groups: ManageableGroup[] = [];
  for await (const page of pages(url, actor.accessToken, groupsSchema))
    groups.push(...(page.groups ?? []));
  return groups.sort((a, b) => a.name.localeCompare(b.name));
}

// ponytail: group membership writes stay simulated until a later change; without GOOGLE_SIMULATION
// they report the Workspace unavailable.
function simulatedDomain() {
  const domain = process.env.GOOGLE_WORKSPACE_DOMAIN;
  if (process.env.GOOGLE_SIMULATION !== "true" || process.env.NODE_ENV === "production" || !domain)
    throw new WorkspaceUnavailable();
  return domain;
}

// The create call may have reached Google even though no answer came back.
export class AccountCreateUncertain extends Error {
  constructor() {
    super("Account creation outcome unknown");
  }
}

// `uncertain.user*` simulates a timeout after the request was sent.
export async function createWorkspaceUser(
  actor: Actor,
  { email, givenName, familyName }: { email: string; givenName: string; familyName: string },
): Promise<{ id: string }> {
  if (process.env.GOOGLE_SIMULATION === "true") {
    simulatedDomain();
    if (email.toLowerCase().startsWith("uncertain.user")) throw new AccountCreateUncertain();
    return { id: `sim-user-${email.toLowerCase()}` };
  }
  // The throwaway password is never stored or returned; the real first-login password is set
  // at handover.
  const created = createdUserSchema.parse(
    await googleSend(`${directory}/users`, actor.accessToken, "POST", {
      primaryEmail: email,
      name: { givenName, familyName },
      password: randomBytes(32).toString("base64url"),
      changePasswordAtNextLogin: true,
    }),
  );
  return { id: created.id };
}

// The temporary password is returned once to the caller and never logged or persisted here.
export async function resetWorkspacePassword(actor: Actor, userKey: string): Promise<string> {
  const password = randomBytes(12).toString("base64url");
  if (process.env.GOOGLE_SIMULATION === "true") {
    simulatedDomain();
    return password;
  }
  await googleSend(
    `${directory}/users/${encodeURIComponent(userKey)}`,
    actor.accessToken,
    "PATCH",
    { password, changePasswordAtNextLogin: true },
  );
  return password;
}

const attempted = new Set<string>();

// `sim-gone` is not listed as manageable (deleted or no longer manageable) and always fails.
export async function addGroupMember(groupId: string, userId: string, _role: string) {
  simulatedDomain();
  if (groupId === "sim-flaky" || groupId === "sim-gone")
    throw new Error("Group membership rejected");
  if (groupId === "sim-recovering" && !attempted.has(`${userId}:${groupId}`)) {
    attempted.add(`${userId}:${groupId}`);
    throw new Error("Group membership rejected");
  }
}
import "server-only";

import type { Actor } from "@/lib/directory";
import { googleSend } from "@/lib/workspace";

const send = "https://gmail.googleapis.com/gmail/v1/users/me/messages/send";

// Sent as the acting administrator. Header values are rejected if they carry a line break,
// so a caller cannot inject extra headers.
export async function sendMailAsActor(
  actor: Actor,
  { to, subject, text }: { to: string; subject: string; text: string },
) {
  // ponytail: development simulation, like the Directory writes; nothing is sent.
  if (process.env.GOOGLE_SIMULATION === "true") return;
  if (/[\r\n]/.test(to) || /[\r\n]/.test(subject)) throw new Error("Mail header rejected");
  // ponytail: one encoded word for the subject; a subject over ~45 bytes needs splitting (RFC 2047).
  const encodedSubject = `=?UTF-8?B?${Buffer.from(subject, "utf8").toString("base64")}?=`;
  const body =
    Buffer.from(text, "utf8")
      .toString("base64")
      .match(/.{1,76}/g)
      ?.join("\r\n") ?? "";
  const message = [
    `To: ${to}`,
    `Subject: ${encodedSubject}`,
    "MIME-Version: 1.0",
    "Content-Type: text/plain; charset=UTF-8",
    "Content-Transfer-Encoding: base64",
    "",
    body,
  ].join("\r\n");
  await googleSend(send, actor.accessToken, "POST", {
    raw: Buffer.from(message, "utf8").toString("base64url"),
  });
}

